	@Test
	void statementContextNameIsDeclaredWithoutBeingAssured() {
		for (StatementPattern.Scope scope : StatementPattern.Scope.values()) {
			StatementPattern statement = new StatementPattern(scope, Var.of("s"), Var.of("p"), Var.of("o"),
					Var.of("g"));
			assertThat(statement.getBindingNames()).containsExactlyInAnyOrder("s", "p", "o", "g");
			assertThat(statement.getAssuredBindingNames()).containsExactlyInAnyOrder("s", "p", "o");
			statement.replaceChildNode(statement.getContextVar(), Var.of("h"));
			assertThat(statement.getBindingNames()).containsExactlyInAnyOrder("s", "p", "o", "h");
			assertThat(statement.clone().getAssuredBindingNames()).containsExactlyInAnyOrder("s", "p", "o");
			statement.replaceChildNode(statement.getContextVar(), null);
			statement.replaceChildNode(statement.getSubjectVar(), Var.of("s2"));
			statement.replaceChildNode(statement.getPredicateVar(), Var.of("p2"));
			statement.replaceChildNode(statement.getObjectVar(), Var.of("o2"));
			assertThat(statement.getBindingNames()).containsExactlyInAnyOrder("s2", "p2", "o2");
			assertThat(statement.getAssuredBindingNames()).containsExactlyInAnyOrder("s2", "p2", "o2");
			StatementPattern valued = new StatementPattern(scope, Var.of("s"), Var.of("p"), Var.of("o"),
					Var.of("g", RDF4J.NIL, false, false));
			assertThat(valued.getAssuredBindingNames()).contains("g");
			StatementPattern constant = new StatementPattern(scope, Var.of("s"), Var.of("p"), Var.of("o"),
					Var.of("g", RDF4J.NIL, true, true));
			assertThat(constant.getAssuredBindingNames()).doesNotContain("g");
		}
		StatementPattern repeated = new StatementPattern(Var.of("s"), Var.of("p"), Var.of("o"), Var.of("s"));
		assertThat(repeated.getAssuredBindingNames()).containsExactlyInAnyOrder("s", "p", "o");
	}

