		Value graph = SimpleValueFactory.getInstance().createIRI("urn:clone-role:graph");
		Var inherited = Var.of("g", graph);
		inherited.setGraphContextDepth(1);
		StatementPattern statement = new StatementPattern(StatementPattern.Scope.NAMED_CONTEXTS,
				Var.of("s"), Var.of("p"), Var.of("o"), inherited);
		Projection select = new Projection(statement, new ProjectionElemList(new ProjectionElem("s")), true);
		select.setProjectionContext(Var.of("g"));
		Join root = new Join(new SingletonSet(), select);
		QueryAlgebraBindingAnalysis original = QueryAlgebraBindingAnalysis.withGuaranteedInputNames(root, Set.of());
		QueryAlgebraBindingAnalysis.ReadOnlyContext input = original.contextAt(select);
		Projection clone = select.clone();
		StatementPattern clonedStatement = (StatementPattern) clone.getArg();
		QueryAlgebraBindingAnalysis fork = original.forClone(clone, input,
				Map.of(clone, select, clonedStatement, statement));
		QueryAlgebraBindingAnalysis fresh = QueryAlgebraBindingAnalysis.withInputContextAndPossibleInputs(clone, input,
				Set.of());
