		And liftedCondition = new And(leftRead, rightRead);
		LeftJoin optional = new LeftJoin(pattern("s", "p", "leftValue"),
				pattern("rightValue", "q", "o"), liftedCondition);
		QueryAlgebraBindingAnalysis analysis = QueryAlgebraBindingAnalysis.withGuaranteedInputNames(optional,
				Set.of());
