	@Test
	void hypotheticalFilterConditionUsesTheHypotheticalOwnerInput() {
		Value actualEntry = SimpleValueFactory.getInstance().createLiteral("actual");
		Extension left = new Extension(new SingletonSet(), new ExtensionElem(Var.of("entry"), "x"));
		Extension argument = new Extension(new SingletonSet(),
				new ExtensionElem(new ValueConstant(actualEntry), "dummy"));
		Filter filter = new Filter(argument, new Bound(Var.of("x")));
		Join root = new Join(left, filter);
		QueryAlgebraBindingAnalysis analysis = QueryAlgebraBindingAnalysis.withBindingValues(root,
				bindings("entry", actualEntry));
		QueryAlgebraBindingAnalysis.ReadOnlyContext hypothetical = QueryAlgebraBindingAnalysis
				.withGuaranteedInputNames(root, Set.of())
				.rootContext();
		AtomicReference<QueryAlgebraBindingAnalysis.ReadOnlyContext> conditionInput = new AtomicReference<>();
		analysis.visitScoped(root, hypothetical, (node, input) -> {
			if (node == filter.getCondition()) {
				conditionInput.set(input);
			}
			return true;
		});

		assertThat(conditionInput.get()).isNotNull();
		assertThat(analysis.bindingState(Var.of("x"), conditionInput.get()))
				.as("the hypothetical owner has no guaranteed entry binding")
				.isEqualTo(QueryAlgebraBindingAnalysis.BindingState.POSSIBLY_BOUND);
		assertThat(conditionInput.get().fixedValues()).doesNotContainKey("x");
	}

	@Test
	void nestedFilterOwnersRetainHypotheticalEntryFacts() {
		Value hypotheticalEntry = SimpleValueFactory.getInstance().createLiteral("hypothetical");
		Extension outerLeft = new Extension(new SingletonSet(), new ExtensionElem(Var.of("entry"), "x"));
		Filter filter = new Filter(new SingletonSet(), new And(new Bound(Var.of("x")), new Bound(Var.of("z"))));
		Join inner = new Join(values(bindings("z", hypotheticalEntry)), filter);
		Join root = new Join(outerLeft, inner);
		QueryAlgebraBindingAnalysis analysis = QueryAlgebraBindingAnalysis.withGuaranteedInputNames(root, Set.of());
		QueryAlgebraBindingAnalysis.ReadOnlyContext hypothetical = QueryAlgebraBindingAnalysis
				.withBindingValues(root, bindings("entry", hypotheticalEntry))
				.rootContext();
		AtomicReference<QueryAlgebraBindingAnalysis.ReadOnlyContext> condition = new AtomicReference<>();
		analysis.visitScoped(root, hypothetical, (node, input) -> {
			if (node == filter.getCondition()) {
				condition.set(input);
			}
			return true;
		});

		assertThat(condition.get()).isNotNull();
		assertThat(condition.get().fixedValues()).containsEntry("x", hypotheticalEntry)
				.containsEntry("z", hypotheticalEntry);
	}

