	@Test
	void lateralRightReceivesDeclaredLeftInputsOnly() {
		Value declaredValue = SimpleValueFactory.getInstance().createIRI("urn:lateral-declared");
		Value hiddenValue = SimpleValueFactory.getInstance().createIRI("urn:lateral-hidden");
		BindingSetAssignment left = values(bindings("declared", declaredValue, "hidden", hiddenValue));
		ExtensionElem assignment = new ExtensionElem(Var.of("declared"), "derived");
		Extension right = new Extension(new SingletonSet(), assignment);
		Lateral lateral = new Lateral(left, right, Set.of("declared"));
		QueryAlgebraBindingAnalysis analysis = QueryAlgebraBindingAnalysis.withGuaranteedInputNames(lateral, Set.of());
		QueryAlgebraBindingAnalysis.ReadOnlyContext input = analysis.contextAt(assignment);

		assertThat(analysis.bindingState(Var.of("declared"), input))
				.as("the declared LATERAL input is visible to the right expression")
				.isEqualTo(QueryAlgebraBindingAnalysis.BindingState.BOUND);
		assertThat(input.fixedValues()).containsEntry("declared", declaredValue);
		assertThat(analysis.bindingState(Var.of("hidden"), input))
				.as("undeclared left outputs are not LATERAL inputs")
				.isEqualTo(QueryAlgebraBindingAnalysis.BindingState.UNBOUND);
	}

	@Test
	void leftJoinOutputFactsKeepRightOnlyNamesNullable() {
		LeftJoin optional = new LeftJoin(pattern("s", "p", "leftValue"),
				pattern("rightValue", "q", "o"));
		QueryAlgebraBindingAnalysis analysis = QueryAlgebraBindingAnalysis.withGuaranteedInputNames(optional,
				Set.of());
		QueryAlgebraBindingAnalysis.OutputFacts facts = analysis.outputFacts(optional);
		QueryAlgebraBindingAnalysis.ReadOnlyContext output = analysis.rootContext().withOutput(facts);

		assertThat(facts.possibleOutputsKnown()).isTrue();
		assertThat(facts.guaranteedOutputsKnown()).isTrue();
		assertThat(facts.possibleOutputs())
				.containsExactlyInAnyOrder("leftValue", "rightValue", "s", "p", "q", "o");
		assertThat(facts.guaranteedOutputs()).containsExactlyInAnyOrder("leftValue", "s", "p");
		assertThat(analysis.bindingState(Var.of("rightValue"), output))
				.as("a right-only OPTIONAL result is nullable because fallback rows remain")
				.isEqualTo(QueryAlgebraBindingAnalysis.BindingState.POSSIBLY_BOUND);
	}

